from functools import cache


@cache
def stairs(n):
    """Ways to climb n steps taking 1 or 2 at a time; each n is worked out once."""
    if n <= 1:
        return 1
    return stairs(n - 1) + stairs(n - 2)


def next_term(n):
    # Replace with the problem's rule. (This example: sum of the cubes of the digits.)
    return sum(int(d) ** 3 for d in str(n))


def chain_length(start, lengths):
    """Distinct terms before the chain from start repeats. lengths is shared
    between calls, so every number met along the way is measured only once."""
    path, position = [], {}
    n = start
    while n not in lengths and n not in position:
        position[n] = len(path)
        path.append(n)
        n = next_term(n)
    if n in lengths:                   # ran into a chain measured earlier
        length = lengths[n]
        for value in reversed(path):
            length += 1
            lengths[value] = length
    else:                              # closed a new loop
        loop_start = position[n]
        for value in path[loop_start:]:
            lengths[value] = len(path) - loop_start
        for i in range(loop_start - 1, -1, -1):
            lengths[path[i]] = lengths[path[i + 1]] + 1
    return lengths[start]


def solve():
    lengths = {}
    longest = max(range(1, 100), key=lambda n: chain_length(n, lengths))
    return stairs(10), chain_length(4, lengths), longest


